files.src/components/Button.jsx:
export function Button({ Label = "Save", Disabled = false, className = "" }) {
  return (
    <button
      type="button"
      disabled={Disabled === true || Disabled === "True"}
      className={`button ${className}`.trim()}
      data-node-id="3:8"
    >
      {Label}
    </button>
  );
}

export default Button;

