export function Chip({
  Size = "M",
  Icon = false,
  Label = "Filter",
  pressed = false,
  onClick
}) {
  return (
    <button
      type="button"
      className={`chip ${Size === "L" ? "chip--l" : ""}`}
      aria-pressed={pressed}
      onClick={onClick}
    >
      {Icon && Size === "L" && (
        <svg
          className="chip-icon"
          width="12"
          height="12"
          viewBox="0 0 12 12"
          fill="currentColor"
          aria-hidden="true"
        >
          <circle cx="6" cy="6" r="6" />
        </svg>
      )}
      <span className="chip-label">{Label}</span>
    </button>
  );
}

export default Chip;

