  return (
    <button
      type="button"
      className={className}
      role="togglebutton"
      aria-pressed={isPressed}
    >
      {Icon && (
        <div
          style={{
            width: '12px',
            height: '12px',
            borderRadius: '50%',
            backgroundColor: 'currentColor',
            flexShrink: 0,
          }}
        />
      )}
      <span>{Label}</span>
    </button>
  );
}

