export default function Field({ className, state = "Default", label, value, onChange, ...props }) {
  const isError = state === "Error";
  const fieldClass = `field ${isError ? "field--error" : ""} ${className || ""}`.trim();

  return (
    <div>
      {label && <label>{label}</label>}
      <input
        type="text"
        className={fieldClass}
        value={value}
        onChange={onChange}
        aria-invalid={isError}
        {...props}
      />
    </div>
  );
}

