export default function Field({ state = "Default", label, ...props }) {
  const errorClass = state === "Error" ? "field--error" : "";

  return (
    <div>
      {label && (
        <label htmlFor={props.id}>
          {label}
        </label>
      )}
      <input
        {...props}
        className={`field ${errorClass} ${props.className || ""}`.trim()}
        type="text"
      />
    </div>
  );
}

