.tag.tag--positive {
  background-color: #d6f5e3;
  color: #136c3a;
}

files.src/components/Tag.jsx:
import './Tag.css';

export default function Tag({ className, Label = 'New', Tone = 'Neutral' }) {
  const classes = ['tag'];

  if (Tone === 'Positive') {
    classes.push('tag--positive');
  }

  if (className) {
    classes.push(className);
  }

  return (
    <div className={classes.join(' ')}>
      <p>{Label}</p>
    </div>
  );
}

